"""Extra original backgrounds with clear visual themes and no remote assets."""
from pathlib import Path
root=Path(__file__).resolve().parent/'assets'
root.mkdir(exist_ok=True)
def scene(name,body):
    (root/f'bg-{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 500" preserveAspectRatio="none">{body}</svg>',encoding='utf-8')

tiles=''.join(f'<path d="M{x} 0V345"/>' for x in range(0,901,75))+''.join(f'<path d="M0 {y}H900"/>' for y in range(0,346,69))
scene('toilet',f'<rect width="900" height="500" fill="#d7e9e4"/><g stroke="#acc9c2" stroke-width="2" fill="none">{tiles}</g><rect y="345" width="900" height="155" fill="#b1c5be"/><g stroke="#8faea5" stroke-width="2"><path d="M0 395H900M0 450H900M140 345L80 500M350 345L330 500M560 345L580 500M770 345L840 500"/></g><rect x="40" y="45" width="210" height="175" rx="10" fill="#eff6ed" stroke="#6e9894" stroke-width="10"/><path d="M64 191L216 66M124 196L228 106" stroke="#c4e3de" stroke-width="12"/><path d="M30 252H260L242 289H52Z" fill="#f6faf1" stroke="#78988d" stroke-width="5"/><path d="M113 288V340H152V289M134 252V226Q133 205 152 211" fill="none" stroke="#6e8f88" stroke-width="9"/><path d="M305 30V338" stroke="#7ca69c" stroke-width="12"/><rect x="508" y="178" width="170" height="124" rx="16" fill="#f4f8ed" stroke="#7d9d91" stroke-width="5"/><rect x="573" y="194" width="42" height="12" rx="5" fill="#9dbdb2"/><path d="M523 353Q524 417 561 430L548 473H654L639 428Q684 411 683 350" fill="#f5f8ed" stroke="#7d9d91" stroke-width="5"/><ellipse cx="603" cy="345" rx="102" ry="42" fill="#f7faf1" stroke="#7d9d91" stroke-width="6"/><ellipse cx="603" cy="345" rx="70" ry="23" fill="#8eb2ae"/><ellipse cx="603" cy="349" rx="48" ry="13" fill="#bbd9d3"/><rect x="732" y="236" width="26" height="9" rx="3" fill="#7a9b92"/><rect x="734" y="243" width="57" height="64" rx="12" fill="#fff9e6" stroke="#9baf9d" stroke-width="4"/><path d="M749 259H779M749 272H779" stroke="#d4d8c4" stroke-width="2"/><rect x="349" y="30" width="142" height="48" rx="8" fill="#eff6e8" stroke="#7d9d91" stroke-width="3"/><text x="420" y="60" text-anchor="middle" font-size="19" font-family="sans-serif" fill="#4c776e">休息一下</text>')

